241	        String address = Owner.normalizeAddress(owner.getAddress());
242	        if (address.isEmpty()) {
243	            return false;
244	        }
245	        owner.setAddress(address);
246	        String telephone = toE164(owner.getTelephone());
247	        if (telephone == null) {
248	            return false;
249	        }
250	        owner.setTelephone(telephone);
251	        if (owner.getEmail() != null) {
252	            owner.setEmail(owner.getEmail().toLowerCase());
