265	     * @param owner the candidate owner being created
266	     * @return the matching existing owner, or empty if none exists
267	     */
268	    private Optional<Owner> findHouseholdMember(Owner owner) {
269	        return this.clinicService.findAllOwners().stream()
270	            .filter(existing -> existing.sameHouseholdAs(owner))
271	            .findFirst();
272	    }
