274	    /**
275	     * Assign the joining owner and an existing household member the same stable
276	     * household identifier. The identifier is derived deterministically from the
277	     * shared household key (last name + address, normalised), so every owner in a
278	     * household resolves to the same value; the existing member is updated when it
279	     * does not already carry it.
280	     *
281	     * @param owner    the owner being created
282	     * @param existing an existing owner in the same household
283	     */
284	    private void joinHousehold(Owner owner, Owner existing) {
285	        String householdId = UUID
286	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
287	        owner.setHouseholdId(householdId);
288	        if (!householdId.equals(existing.getHouseholdId())) {
