294	    /**
295	     * Count the existing owners that share the given owner's first and last name,
296	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
297	     * before the new owner is saved, so the result reflects only owners that
298	     * already existed at creation time.
299	     *
300	     * @param owner the candidate owner being created
301	     * @return the number of existing namesakes
302	     */
303	    private int countNamesakes(Owner owner) {
304	        String firstName = normalizeName(owner.getFirstName());
305	        String lastName = normalizeName(owner.getLastName());
306	        return (int) this.clinicService.findAllOwners().stream()
307	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
308	                && normalizeName(existing.getLastName()).equals(lastName))
309	            .count();
310	    }
