316	    /**
317	     * Build the next customer code, formatted {@code <LAST3>-<NNNN>}: LAST3 is the
318	     * upper-cased first three letters of the given last name and NNNN is a global
319	     * 4-digit zero-padded sequence equal to one more than the current number of
320	     * owners (e.g. {@code SMI-0007}).
321	     *
322	     * @param lastName the owner's last name
323	     * @return the assigned customer code
324	     */
325	    private String nextCustomerCode(String lastName) {
326	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
327	        long sequence = this.clinicService.findAllOwners().size() + 1L;
328	        return String.format("%s-%04d", last3, sequence);
329	    }
330	
331	    /**
332	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
333	     * code when present, otherwise assume country code '+61' and drop a single
334	     * leading '0' from the national digits. Spaces, dashes and brackets are
335	     * stripped. The result must contain 8 to 15 digits after the '+'.
336	     *
337	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
338	     *         input cannot form a valid E.164 number.
339	     */
340	    private static String toE164(String raw) {
341	        if (raw == null) {
342	            return null;
343	        }
344	        String cleaned = raw.replaceAll("[\\s()-]", "");
345	        String digits;
346	        if (cleaned.startsWith("+")) {
347	            digits = cleaned.substring(1);
348	        } else {
349	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
350	            digits = "61" + national;
351	        }
352	        if (!digits.matches("\\d{8,15}")) {
353	            return null;
354	        }
355	        return "+" + digits;
356	    }
